               <div><Label className="text-xs">Fast Set</Label><Input type="number" className="h-8" value={form.mix_fast_set_price ?? 248.00} onChange={e => set('mix_fast_set_price', parseFloat(e.target.value) || 0)} step="0.01" min="0" /></div>
