          {admix.map((a) => (
            <label key={a.id} className={`flex gap-2 items-start text-xs ${unavailable ? "text-gray-400" : "text-gray-600"}`}>
              <input
                type="checkbox"
                className="mt-0.5"
                disabled={unavailable}
                checked={admixtures.includes(a.id)}
                onChange={() => toggleAdmix(a.id)}
              />
              <span>
                <span className="font-medium text-gray-800">{a.name}</span> — {hasFoundationCostSnapshot(a.price) ? `${money(a.price)}/CY` : "price unavailable"}
                <span className="block text-[11px] text-gray-400">{a.desc}</span>
              </span>
            </label>
          ))}
        </div>
      </div>

      {trucks.length > 0 && (
        <div className="mt-3 pt-3 border-t border-gray-100 space-y-1">
          {trucks.map((t, i) => (
            <div key={i} className="flex justify-between text-xs text-gray-600">
              <span>
                Truck {i + 1} — {cy(t.roundedYards)}
                {Number.isFinite(t.smallOrderFee) && t.smallOrderFee > 0 && ` (small load ${money(t.smallOrderFee)})`}
                {Number.isFinite(t.fuelFee) && t.fuelFee > 0 && ` + fuel ${money(t.fuelFee)}`}
              </span>
              <span className="font-medium text-gray-800">{amt(t.cost)}</span>
            </div>
          ))}
          {(delivery?.additionalStopsCost ?? 0) > 0 && (
            <div className="flex justify-between text-xs text-gray-600">
              <span>Additional sign locations / stops</span>
              <span className="font-medium text-gray-800">{amt(delivery.additionalStopsCost)}</span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { deleteEntityIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { base44 } from "@/api/base44Client";
import { staffEntities } from "@/components/staff/staffEntities";

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  if (a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "") {
    if (Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
      return Math.abs(Number(a) - Number(b)) <= 0.000001;
    }
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

function matchesPayload(row = {}, payload = {}) {
  return Object.entries(payload || {}).every(([field, value]) => sameValue(row?.[field], value));
}

export async function createInventoryRecordWithRecovery({
  entity,
  data = {},
  nameField,
  label = "Inventory item",
} = {}) {
  const field = String(nameField || "").trim();
  const name = String(data?.[field] ?? "").trim();
  if (!field || !name || typeof entity?.filter !== "function" || typeof entity?.create !== "function") {
    throw new Error(`${label} could not initialize its retry-safe create.`);
  }

  const readCandidates = async () => {
    const rows = await entity.filter({ [field]: data[field] });
    if (!Array.isArray(rows)) throw new Error(`${label} lookup did not return a record list.`);
    return rows;
  };

  const before = await readCandidates();
  const beforeIds = new Set(before.map((row) => row?.id).filter(Boolean));

  let created = null;
  let createError = null;
  try {
    created = await entity.create(data);
  } catch (error) {
    createError = error;
  }

  if (created?.id) {
    const verified = typeof entity.get === "function" ? await entity.get(created.id).catch(() => null) : null;
    if (verified?.id && !matchesPayload(verified, data)) {
      throw new Error(`${label} was created but its stored values do not match this save. Reload the inventory and review the new row before retrying.`);
    }
    return { record: verified?.id ? verified : created, status: "created" };
  }

  const after = await readCandidates();
  const newExactMatches = after.filter((row) => !beforeIds.has(row?.id) && matchesPayload(row, data));
  if (newExactMatches.length === 1) {
    return { record: newExactMatches[0], status: "recovered" };
  }
  if (newExactMatches.length > 1) {
    throw new Error(`${label} may have been created more than once while the create response was unavailable. No inventory rows were deleted; reload and review the new matching rows before retrying.`);
  }

  if (createError) throw createError;
  throw new Error(`${label} could not verify whether it was created. Reload the inventory before retrying.`);
}

export async function deleteInventoryRecordIfUnchanged({
  entity,
  record,
  nameField,
  label = "Inventory item",
} = {}) {
  const field = String(nameField || "").trim();
  const guardFields = field && Object.prototype.hasOwnProperty.call(record || {}, field)
    ? { [field]: record[field] }
    : {};
  return deleteEntityIfUnchanged({
    entity,
    record,
    guardFields,
    label,
  });
}

// Cascade-check before inventory delete: estimate Parts link to inventory rows
// via inventory_item_id. Deleting a referenced row would orphan those links, so
// callers must run this first and block the delete when references exist.
export async function findInventoryPartReferences(recordId) {
  const id = String(recordId || "");
  if (!id || typeof base44?.entities?.BuilderPart?.filter !== "function") {
    throw new Error("Estimate Part references could not be verified.");
  }
  const rows = await base44.entities.BuilderPart.filter({ inventory_item_id: id });
  const list = Array.isArray(rows) ? rows : [];
  return {
    count: list.length,
    names: list.map((p) => p.part_name || p.part_key || "Part").slice(0, 5),
  };
}

// Usage history: resolve estimate Parts → BuilderProducts → distinct estimates
// so inventory rows can show a "used in N estimates" badge. Sequential product
// reads are bounded by how many products consume the item.
export async function findInventoryEstimateUsage(recordId) {
  const id = String(recordId || "");
  if (!id || typeof base44?.entities?.BuilderPart?.filter !== "function" || typeof base44?.entities?.BuilderProduct?.get !== "function") {
    throw new Error("Estimate usage could not be verified.");
  }
  const rows = await base44.entities.BuilderPart.filter({ inventory_item_id: id });
  const parts = Array.isArray(rows) ? rows : [];
  const productIds = [...new Set(parts.map((p) => p?.builder_product_id).filter(Boolean))];
  const estimateIds = new Set();
  for (const productId of productIds) {
    const product = await base44.entities.BuilderProduct.get(productId).catch(() => null);
    if (product?.estimate_id) estimateIds.add(product.estimate_id);
  }
  return { parts: parts.length, products: productIds.length, estimates: estimateIds.size, estimateIds: [...estimateIds].slice(0, 25) };
}

const COST_FIELD_RX = /cost|rate|price/i;

// Writes InventoryCostHistory rows for any cost/rate/price-named field whose
// value changed between the loaded row and the saved payload. Best-effort:
// failures are swallowed so the audit never blocks an inventory save.
export async function recordInventoryCostChanges({ itemId, entityKey, before = {}, after = {}, fields = [], note = "Inventory edit", changedBy = "" } = {}) {
  if (!itemId || typeof staffEntities?.InventoryCostHistory?.create !== "function") return 0;
  const costFields = new Set((fields || []).filter((f) => f?.name && COST_FIELD_RX.test(f.name)).map((f) => f.name));
  const candidates = new Set([...costFields, ...Object.keys(after).filter((k) => COST_FIELD_RX.test(k))]);
  let written = 0;
  for (const field of candidates) {
    const oldVal = Number(before[field]);
    const newVal = Number(after[field]);
    if (!Number.isFinite(oldVal) || !Number.isFinite(newVal) || Math.abs(oldVal - newVal) <= 0.000001) continue;
    await staffEntities.InventoryCostHistory.create({
      inventory_item_id: String(itemId),
      entity_key: String(entityKey || ""),
      cost_field: String(field),
      old_cost: oldVal,
      new_cost: newVal,
      changed_by: String(changedBy || ""),
      note: String(note || ""),
    }).catch(() => { /* audit must not fail the save */ });
    written += 1;
  }
  return written;
}

export async function loadInventoryCostHistory({ itemId, entityKey = "", limit = 5 } = {}) {
  if (!itemId || typeof staffEntities?.InventoryCostHistory?.filter !== "function") return [];
  const query = entityKey
    ? { inventory_item_id: String(itemId), entity_key: String(entityKey) }
    : { inventory_item_id: String(itemId) };
  const rows = await staffEntities.InventoryCostHistory.filter(query).catch(() => []);
  const list = Array.isArray(rows) ? rows : [];
  return list
    .sort((a, b) => String(b?.created_date || "").localeCompare(String(a?.created_date || "")))
    .slice(0, limit);
}

import { expectedEntityFields, replaceEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";

export async function setExclusiveBooleanSafely({
  entity,
  targetId,
  field,
  next,
  expectedTargetUpdatedAt = "",
  expectedRowVersions = null,
  readRows,
  label = "exclusive selection",
} = {}) {
  if (!entity || !targetId || !field || typeof readRows !== "function") {
    throw new Error(`${label} could not initialize safely.`);
  }

  const before = await readRows();
  if (!Array.isArray(before)) throw new Error(`${label} could not verify the complete record set.`);
  const target = before.find((row) => row.id === targetId);
  if (!target?.id) throw new Error(`${label} target no longer exists. Reload before changing it.`);
  if (expectedTargetUpdatedAt && String(target.updated_date || "") !== String(expectedTargetUpdatedAt)) {
    throw new Error(`${label} target changed in another session. Reload before changing it.`);
  }

  let confirmedWrites = 0;
  let plannedWrites = 1;
  const targetPatch = { [field]: !!next };
  await replaceEntityFieldsIfUnchanged({
    entity,
    id: target.id,
    expectedUpdatedAt: target.updated_date || "",
    expectedFields: expectedEntityFields(target, targetPatch),
    nextFields: targetPatch,
    label: `${label} target`,
  });
  confirmedWrites += 1;

  if (next) {
    const afterTarget = await readRows();
    if (!Array.isArray(afterTarget)) {
      throw new Error(`${label} target was saved, but the complete record set could not be re-verified.`);
    }
    const others = afterTarget.filter((row) => row.id !== targetId && row[field] === true);
    plannedWrites += others.length;
    for (const row of others) {
      if (expectedRowVersions && typeof expectedRowVersions === "object") {
        if (!Object.prototype.hasOwnProperty.call(expectedRowVersions, row.id)) {
          throw new Error(`${label} detected a new concurrent selection before it could be cleared. Reload before retrying.`);
        }
        const expectedVersion = expectedRowVersions[row.id];
        if (expectedVersion && String(row.updated_date || "") !== String(expectedVersion)) {
          throw new Error(`${label} detected a concurrent change to another selected record before it could be cleared. Reload before retrying.`);
        }
      }
      const clearPatch = { [field]: false };
      try {
        await replaceEntityFieldsIfUnchanged({
          entity,
          id: row.id,
          expectedUpdatedAt: row.updated_date || "",
          expectedFields: expectedEntityFields(row, clearPatch),
          nextFields: clearPatch,
          label: `${label} previous selection`,
        });
        confirmedWrites += 1;
      } catch (error) {
        throw new Error(`${label} stopped after ${confirmedWrites} of ${plannedWrites} required changes were confirmed. Reload before retrying; no remaining records were skipped automatically. ${error?.message || ""}`.trim());
      }
    }
  }

  const finalRows = await readRows();
  if (!Array.isArray(finalRows)) {
    throw new Error(`${label} changes were made, but final verification could not load the complete record set.`);
  }
  const finalTarget = finalRows.find((row) => row.id === targetId);
  if (!finalTarget || !!finalTarget[field] !== !!next) {
    throw new Error(`${label} could not verify the final target state. Reload before retrying.`);
  }
  if (next) {
    const primaries = finalRows.filter((row) => row[field] === true);
    if (primaries.length !== 1 || primaries[0].id !== targetId) {
      throw new Error(`${label} detected another concurrent selection during final verification. Reload before retrying.`);
    }
  }

  return { rows: finalRows, target: finalTarget, confirmedWrites, plannedWrites };
}

export async function replaceRelationshipIdsIfUnchanged({
  entity,
  row,
  field,
  nextIds,
  label = "equipment relationship",
} = {}) {
  if (!row?.id || !field || !Array.isArray(nextIds)) throw new Error(`${label} could not initialize safely.`);
  const patch = { [field]: nextIds };
  return replaceEntityFieldsIfUnchanged({
    entity,
    id: row.id,
    expectedUpdatedAt: row.updated_date || "",
    expectedFields: expectedEntityFields(row, patch),
    nextFields: patch,
    label,
  });
}

